import{_ as t,o as s,c as a,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — List Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-1-list-agency/sequence-flow.md","filePath":"feature/agency-workspace/3-4-1-list-agency/sequence-flow.md"}'),i={name:"feature/agency-workspace/3-4-1-list-agency/sequence-flow.md"};function n(r,e,l,c,h,d){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="sequence-flow-—-list-agency" tabindex="-1">Sequence Flow — List Agency <a class="header-anchor" href="#sequence-flow-—-list-agency" aria-label="Permalink to &quot;Sequence Flow — List Agency&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.1). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — signed in; may own several Agencies and may belong to other Agencies as a Member.</li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agencies</code>, <code>agency_members</code>).</li></ul><hr><h2 id="flow-a-—-view-the-agency-list" tabindex="-1">Flow A — View the Agency list <a class="header-anchor" href="#flow-a-—-view-the-agency-list" aria-label="Permalink to &quot;Flow A — View the Agency list&quot;">​</a></h2><ol><li>User → Client: signs in and opens the Agencies page, which is the default landing page when the user owns or belongs to at least one Agency.</li><li>Client → System: requests the Agency list of the signed-in user (<code>GET /api/v1/agencies</code>).</li><li>System — build the list: a. Collects the Agencies the user owns, excluding those that are soft-deleted. b. Collects the Agencies where the user holds a member record and merges them into the same set of identifiers, removing duplicates. c. Loads the merged set by identifier, filters out any Agency that is soft-deleted once more, and maps each remaining Agency to its full profile.</li><li>System → Client: the list of Agency profiles, empty when the user owns or belongs to none.</li><li>Client: renders one card per Agency. When the list is empty, it shows the empty state with the &quot;Create new Agency&quot; call to action (3.4.3).</li><li>User selects a card → the Client moves into that Agency, using the Agency profile of 3.4.4 because the Agency Dashboard of 3.4.2 has no screen of its own yet.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>List</td><td>None — the list is always returned, including when it is empty</td><td>—</td><td>—</td></tr></tbody></table><p>The feature has no business failure path. Only the shared session failure applies: a request without a valid session is rejected with <code>401 UNAUTHORIZED</code> before it reaches the Agency logic.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>No divergence from <code>spec.md</code>: the result merges the Agencies the user owns with the Agencies the user belongs to, even though the feature is named from the Owner&#39;s point of view. <code>spec.md</code> states this in its business rules.</li></ul>',13)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
